-- 特征（8）：双口径 src_table / match_src
INSERT INTO feature_def (feature_id, feature_code, feature_name, risk_type, feature_cat, direction, object_scope, value_type, src_table, match_src, match_expr, time_window_min, min_sample, status, description) VALUES
('F001', 'NIGHT_VENUE', '夜间酒水场所集中度', 1, 1, 1, 1, 2, 'case_info', 'consume_record', '该区域该小时内含酒水消费的不同场所数 ≥ 2', 60, 5, 1, '区域级聚合特征；对象本身按小时定义，因此不用"是不是深夜"这种恒真条件'),
('F002', 'KTV_CONSUME', '在饭店/KTV/酒吧等场所含酒水消费', 1, 2, 1, 3, 1, 'case_info', 'consume_record', '窗口内 has_alcohol = 1', 180, 5, 1, '区域级看"该区域该小时有没有酒水消费"，个人级看"这个人在窗口内有没有"'),
('F003', 'NO_TAXI', '无网约车或代驾订单', 1, 3, 1, 2, 1, 'case_info', 'taxi_order', '窗口内 NOT EXISTS 已完成订单（type IN (1,2)）', 180, 5, 1, '只有 order_status=1 的订单才算数，取消单不能证明他没开车'),
('F004', 'SELF_DRIVE', '自行驾车驶出', 1, 4, 1, 1, 2, 'case_info', 'vehicle_track', '该区域该小时内驶出车辆数 ≥ 5', 60, 5, 1, '区域级聚合；方向必须是"驶出区域"（direction=2）；不推断具体驾驶人'),
('F005', 'FAR_FROM_HOME', '离家较远', 1, 1, 1, 2, 1, 'case_info', 'person_info', '消费场所所属区域 ≠ 居住区域（home_area_id）', 180, 5, 1, '用"跨区域"近似"离家距离远"，避免在库里引入经纬度和大圆距离计算'),
('F006', 'HAS_DRIVER', '有代驾订单（反例）', 1, 5, 2, 2, 1, 'case_info', 'taxi_order', '窗口内存在 order_type = 2 且已完成的订单', 180, 5, 1, '命中则扣分，counter_block=1 时直接阻断线索生成'),
('F008', 'CASE_HISTORY', '历史涉案', 1, 4, 1, 2, 2, 'case_info', 'v_case_history', '该人员 90 天内历史案件数 ≥ 1', 0, 5, 1, '只能读 v_case_history，视图已把 history_cutoff 之后的案件滤掉'),
('F009', 'DRUNK_HISTORY', '历史醉驾', 1, 4, 1, 2, 1, 'case_info', 'v_case_history', '该人员历史案件中存在 alcohol_value ≥ 80', 0, 5, 1, '同上，历史档案特征，不得读 case_info 原表');
