-- 触发器写审计时 op_time 取 NOW()（导入时刻）；这里按核查时刻回填，保证审计时间线从属于业务事件
UPDATE audit_log a
  JOIN clue_feedback f ON f.clue_id = a.record_pk AND f.check_result IN (1,2)
   SET a.op_time = f.check_time
 WHERE a.table_name = 'risk_clue' AND a.op_type = 4 AND a.operator_tag <> 'system';

